package com.medbook.dto;

import jakarta.validation.constraints.FutureOrPresent;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.time.LocalDate;
import java.time.LocalTime;

/**
 * Request body for {@code POST /api/v1/appointments}.
 *
 * <p>It contains only what a client is allowed to choose: who is booking, with which
 * doctor, and when. Everything else is decided server-side:</p>
 *
 * <ul>
 * <li>the appointment ID and the {@code created_at} / {@code updated_at} timestamps are
 *     generated by the database,</li>
 * <li>{@code status} is set by the service (always {@code SCHEDULED} on creation),</li>
 * <li>the initial status history row is written by the service,</li>
 * <li>{@code consultation_fee_snapshot} is copied from the doctor by the service so a
 *     client can neither inflate nor discount the price.</li>
 * </ul>
 *
 * <p>The field annotations only reject structurally invalid requests (missing or negative
 * IDs, a date in the past). Business rules such as "is this window inside the doctor's
 * availability?" stay in {@link com.medbook.service.AppointmentService}.</p>
 *
 * @param patientId       ID of the patient booking the appointment (must be a positive number)
 * @param doctorId        ID of the doctor being booked (must be a positive number)
 * @param appointmentDate the clinic visit date, today or later
 * @param startTime       window start, for example {@code "10:00"}
 * @param endTime         window end, which must be after {@code startTime}
 */
public record CreateAppointmentRequest(

        @NotNull(message = "patientId is required")
        @Positive(message = "patientId must be a positive number")
        Long patientId,

        @NotNull(message = "doctorId is required")
        @Positive(message = "doctorId must be a positive number")
        Long doctorId,

        @NotNull(message = "appointmentDate is required")
        @FutureOrPresent(message = "appointmentDate must be today or in the future")
        LocalDate appointmentDate,

        @NotNull(message = "startTime is required")
        LocalTime startTime,

        @NotNull(message = "endTime is required")
        LocalTime endTime
) {
}
